function sessUser(){return S.users.filter(function(u){return u.id===S.dec.role;})[0]||S.users[0];}
function myRole(){return sessUser().role;}
function isPriv(){return myRole()!=='operator';}
function roleLabel(r){return r==='operator'?'Operador':r==='admin'?'Administrador':'Propietario';}
function isOwnerLike(r){return r==='owner';}
function ROLE_DESC(r){return r==='owner'?'Controla la cuenta: usuarios, roles, política y mercado.':r==='admin'?'Gestiona operadores, clientes, ventas, política y mercado.':'Registra ventas, pagos y seguimiento; sus pagos manuales quedan por aprobar.';}
