var PLAN_HINT={unico:'Un solo pago a los días indicados.',cuotas:'Cuotas iguales, cada cierto número de días.',inicial_saldo:'Un porcentaje inicial y el resto en un solo pago.',inicial_cuotas:'Un porcentaje inicial y el resto en cuotas iguales.',inicial_val:'Un porcentaje inicial y el resto por avance de obra o servicio (valuaciones).',val:'Todo por valuaciones: cada una se paga cuando el cliente la aprueba.',recepcion:'El pago vence a los días de que el cliente confirma la recepción.',custom:'Tú defines cada cuota: concepto, días y monto.'};
var PLAN_KINDS=[['unico','Pago único'],['cuotas','Cuotas fijas'],['inicial_saldo','Inicial + saldo'],['inicial_cuotas','Inicial + cuotas'],['inicial_val','Inicial + valuaciones'],['val','Solo valuaciones'],['recepcion','Contra recepción'],['custom','Cuotas personalizadas']];
