 if(k==='cuotas'){planSplit(total,cfg.n).forEach(function(v,i){add('cuota','Cuota '+(i+1)+' de '+cfg.n,v,cfg.first+i*cfg.gap);});}
 else if(k==='inicial_saldo'){add('inicial','Inicial',ini,cfg.iniDays||0);add('saldo','Saldo',rest,cfg.days);}
 else if(k==='inicial_cuotas'){add('inicial','Inicial',ini,cfg.iniDays||0);planSplit(rest,cfg.n).forEach(function(v,i){add('cuota','Cuota '+(i+1)+' de '+cfg.n,v,cfg.first+i*cfg.gap);});}
 else if(k==='inicial_val'||k==='val'){var base=k==='val'?total:rest,ret=r2(base*(cfg.ret||0)/100),net=r2(base-ret);if(k==='inicial_val')add('inicial','Inicial',ini,cfg.iniDays||0);planSplit(net,cfg.n).forEach(function(v,i){add('valuacion','Valuación '+(i+1)+' de '+cfg.n,v,null,{term:cfg.term,state:'por emitir'});});if(ret>0)add('retencion','Retención de garantía',ret,null,{term:cfg.retTerm,state:'por liberar'});}
