function termsDisc(p){return (S.dec.discount==='on'&&p&&p.pct)?{pct:p.pct,pctDays:p.pctDays}:null;}
function termsSale(s){return termsOf(s.planCfg&&s.planCfg.kind!=='unico'?s.planCfg:null,s.amount,s.days,termsDisc(s.snapshot||S.policy));}
