function termsGroup(s){var k=(s.planCfg&&s.planCfg.kind)||(s.items&&s.items.length>1?'custom':'unico');if(k==='val'||k==='inicial_val')return 'stg';if(k==='inicial_saldo'||k==='inicial_cuotas'||(k==='recepcion'&&s.planCfg.ini>0))return 'adv';if(k==='cuotas'||k==='custom')return 'inst';var N=k==='recepcion'?(s.planCfg.term||0):s.days;return N<=0?'cod':N<=15?'n15':N<=30?'n30':N<=60?'n60':'n90';}
