 if((k==='val'||k==='inicial_val')&&c.cbase>0&&t>c.cbase)return 'El monto de la venta supera el contrato base ('+mt(c.cbase,f.cur||'USD')+').';
 if((k==='cuotas'||k==='inicial_cuotas')&&!(need(c.n,2,12)&&c.gap>=1&&c.first>=1))return 'Revisa el número de cuotas (2 a 12), los días entre cuotas y la primera fecha.';
 if(k.indexOf('inicial')===0||k==='recepcion'){if(!(need(c.ini,k==='recepcion'?0:1,90)))return 'El inicial debe estar entre '+(k==='recepcion'?0:1)+' % y 90 %.';if(!(c.iniDays>=0))return 'Los días del inicial no pueden ser negativos.';}
 if(k==='inicial_saldo'&&!(c.days>=1))return 'Escribe los días del saldo.';
