 if(k==='recepcion'&&!(c.term>=1))return 'Escribe los días de pago desde la recepción.';
 if(k==='custom'){var its=c.items||[];if(its.length<2)return 'Agrega al menos dos cuotas.';if(its.some(function(x){return !(x.amount>0)||!(x.days>=0);}))return 'Cada cuota necesita un monto mayor que cero y los días desde la activación.';var sm=r2(its.reduce(function(a,x){return a+x.amount;},0));if(Math.abs(sm-t)>0.01)return 'Las cuotas suman '+mt(sm,f.cur||'USD')+' y el monto es '+mt(t,f.cur||'USD')+'.';}
