 if(k==='inicial_saldo')return row(n('ini','Inicial (%)'),n('iniDays','Inicial vence a los (días)','0 = al activar.'))+n('days','Saldo vence a los (días)','Desde la activación.');
 if(k==='inicial_cuotas')return row(n('ini','Inicial (%)'),n('iniDays','Inicial vence a los (días)','0 = al activar.'))+row(n('n','Número de cuotas'),n('gap','Cada (días)'))+n('first','Primera cuota a los (días)','Desde la activación.');
 if(k==='inicial_val')return row(n('ini','Inicial (%)'),n('iniDays','Inicial vence a los (días)','0 = al activar.'))+row(n('n','Número de valuaciones'),n('term','Pago a los (días) de aprobada'))+row(n('ret','Retención de garantía (%)','Se paga tras la aceptación final.'),n('retTerm','Retención se paga a los (días)'))+ctr();
