function pgR(k,total){var sz=S.psz||10,pages=Math.max(1,Math.ceil(total/sz)),p=Math.min(Math.max(S.more[k]||1,1),pages);return {a:(p-1)*sz,b:Math.min(total,p*sz),p:p,pages:pages,sz:sz};}
