 if(total<=PSZ[0]) return '';
 var r=pgR(k,total),nums=[],add=function(n){if(nums.indexOf(n)<0)nums.push(n);};
 add(1);for(var i=r.p-1;i<=r.p+1;i++)if(i>1&&i<r.pages)add(i);if(r.pages>1)add(r.pages);nums.sort(function(x,y){return x-y;});
 var btns='',prev=0;nums.forEach(function(n){if(prev&&n-prev>1)btns+='<span class="pgd" aria-hidden="true">…</span>';btns+='<button class="pgb'+(n===r.p?' on':'')+'" data-act="pgGo" data-k="'+k+'" data-p="'+n+'"'+(n===r.p?' aria-current="page"':'')+' aria-label="Página '+n+'">'+n+'</button>';prev=n;});
