var POLF=[['limUSD','Límite inicial','usd'],['maxDays','Plazo máximo','days'],['pct','Descuento por pronto pago','pct'],['pctDays','Días de anticipación del descuento','days'],['retries','Reintentos de cobro','n'],['retryDays','Días entre reintentos','days'],['moraDays','Días de atraso para aplicar las medidas','days'],['moraPause','Pausar nuevas ventas al cliente','yn'],['chBefore','Aviso antes del vencimiento','days'],['chOnDue','Avisar el día del vencimiento','yn'],['chEvery','Repetir cada','days'],['chMax','Máximo de avisos','n'],['chFollow','Después, un aviso cada','days'],['claimGrace','Margen tras un pago no recibido','days'],['reschedScore','El score mide contra','rs']];
function polFmt(t,v){return t==='rs'?(v==='new'?'La fecha reprogramada':'El vencimiento original'):t==='usd'?mtL(v,BC(),'es'):t==='ves'?mtL(v,'VES','es'):t==='days'?v+(v===1?' día':' días'):t==='pct'?v+' %':t==='yn'?(v?'Sí':'No'):String(v);}
function polDiff(a,b){return POLF.filter(function(f){return a[f[0]]!==b[f[0]];}).map(function(f){return {l:f[1],a:polFmt(f[2],a[f[0]]),b:polFmt(f[2],b[f[0]])};});}
function modeLast(){return S.polLog.filter(function(e){return e.k==='mode';})[0]||null;}
function offInfo(){var l=modeLast();if(creditOn()||!l||l.to!=='off')return null;var sd=parseInt(String(l.t).split('|')[0],10),ss=S.sales.filter(function(x){return x.noCredit&&x.status!=='draft'&&dn(x.issue)>=sd;}),sums={};ss.forEach(function(x){sums[x.cur]=(sums[x.cur]||0)+x.amount;});return {since:addDays(TODAY,sd-dn(TODAY)),n:ss.length,sums:sums};}
