function attention(){
 var out=[],tail=[];
 if(isPriv()&&retOn()){var rv=[],lt=[];S.sales.forEach(function(x){retAll(x).forEach(function(q){var t=retSt(q);if(t==='review')rv.push(x);if(t==='late')lt.push(x);});});if(rv.length)tail.push({h:'#/sales/'+rv[0].id,t:TL('Retenciones','Withholdings'),sub:rv.length+TL(rv.length===1?' comprobante de retención por revisar':' comprobantes de retención por revisar',rv.length===1?' withholding voucher to review':' withholding vouchers to review'),c:chip('Por revisar','info')});if(lt.length)tail.push({h:'#/sales/'+lt[0].id,t:TL('Retenciones','Withholdings'),sub:lt.length+TL(lt.length===1?' retención vencida sin comprobante':' retenciones vencidas sin comprobante',lt.length===1?' overdue withholding without voucher':' overdue withholdings without voucher'),c:chip('Vencida','err')});}
 if(isPriv()&&S.bill){if(S.bill.deb.state==='failed'&&isOwnerLike(myRole()))tail.push({h:'#/config/billing',t:'Facturación de Fluye',sub:'No se pudo cobrar el último débito',c:chip('Revisar','err')});var bq=billPending().filter(function(x){return x.state!=='waived';}).length;if(bq)tail.push({h:'#/config/billing',t:'Facturación de Fluye',sub:bq+TL(bq===1?' venta por confirmar: ¿te pagaron por fuera?':' ventas por confirmar: ¿te pagaron por fuera?',bq===1?' sale to confirm: were you paid outside Fluye?':' sales to confirm: were you paid outside Fluye?'),c:chip('Por confirmar','warn')});}
 S.sales.filter(function(x){return x.status==='draft'&&x.proposal&&propState(x)==='accepted';}).forEach(function(x){out.push({h:'#/sales/'+x.id,t:x.id+' · '+buyer(x.buyerId).name,sub:'Cotización aceptada · '+mt(x.amount,x.cur),c:chip('Lista para activar','ok')});});
 S.sales.filter(function(x){return x.status==='active';}).map(function(x){return {x:x,ci:chainInfo(x)};}).filter(function(e){return e.ci&&e.ci.manual&&!handled(e.x);}).sort(function(a,b){return a.ci.ni.n-b.ci.ni.n;}).forEach(function(e){
  var x=e.x,ci=e.ci;out.push({h:'#/sales/'+x.id,t:x.id+' · '+buyer(x.buyerId).name+(multiPlan(x)?' · '+ci.ni.c.label:''),sub:reasonSub(ci)+' · '+mt(ci.ni.bal,x.cur),c:reasonChip(ci),rem:x.id});});
 if(isPriv())S.sales.forEach(function(x){openReqs(x).forEach(function(r){out.unshift({h:'#/sales/'+x.id,t:x.id+' · '+buyer(x.buyerId).name,sub:'Solicitud de '+(r.type==='resched'?'reprogramación':'anulación')+' de '+r.by+' · '+reqLine(r),c:chip('Por aprobar','info')});});});
 if(isPriv())S.sales.forEach(function(x){openClaims(x).forEach(function(cl){out.push({h:'#/sales/'+x.id,t:x.id+' · '+buyer(x.buyerId).name,sub:(cl.by==='cliente'?'Informó un pago':'Pago pendiente de aprobación')+' · '+mt(cl.amount,x.cur),c:chip('Por confirmar','info')});});});
 S.sales.forEach(function(x){(x.claims||[]).forEach(function(cl){if(cl.status==='returned'&&!cl.ack&&cl.byName===S.seller.name)out.unshift({h:'#/sales/'+x.id,t:x.id+' · '+buyer(x.buyerId).name,sub:'Pago devuelto: '+cl.reason+' · '+mt(cl.amount,x.cur),c:chip('Devuelto','warn')});});});
 S.buyers.forEach(function(b){if(!hasCredit(b))return;var p=exposure(b)/b.limit;
  if(p>=NEARLIM)out.push({h:'#/buyers/'+b.id,t:b.name,sub:'Usa el '+Math.round(p*100)+'% de su límite',c:chip('Cerca del límite','warn')});
  if(b.fresh)out.push({h:'#/buyers/'+b.id,t:b.name,sub:'Su perfil suma un pago observado nuevo',c:chip('Evidencia actualizada','info')});
  if(!b.hist&&!evidence(b).n)out.push({h:'#/buyers/'+b.id,t:b.name,sub:'Sin evidencia todavía: no hay historial ni pagos observados',c:chip('Sin historial')});});
 S.sales.filter(function(x){return x.status==='draft';}).forEach(function(x){out.push({h:'#/sales/'+x.id+'/review',t:'Borrador '+x.id,sub:'Sin activar · '+mt(x.amount,x.cur),c:chip('Borrador')});});
 return out.concat(tail);
}
function greet(){var h=new Date().getHours();return h<12?'Buenos días':h<19?'Buenas tardes':'Buenas noches';}
function ini2(n){var skip={y:1,e:1,de:1,del:1,la:1,las:1,los:1,el:1,al:1,en:1,para:1,ca:1,sa:1,srl:1,llc:1},w=n.replace(/[^A-Za-zÁÉÍÓÚÑáéíóúñ ]/g,'').split(' ').filter(Boolean),k=w.filter(function(x){return !skip[x.toLowerCase()];});if(k.length<2)k=w;return k.slice(0,2).map(function(x){return x[0].toUpperCase();}).join('');}
function syncLimits(){S.buyers.forEach(function(b){if(!b.custom&&!isPn(b))b.limit=S.policy.limUSD;});}
function chainOffs(){var p=S.policy,o=[],k=1;if(p.chBefore>0)o.push(-p.chBefore);if(p.chOnDue)o.push(0);while(o.length<p.chMax){o.push(k*p.chEvery);k++;}return o.slice(0,p.chMax);}
function graceClaim(s){return (s.claims||[]).filter(function(c){return c.status==='notreceived'&&c.rejAt&&dn(TODAY)-dn(c.rejAt)<S.policy.claimGrace;})[0]||null;}
function inGrace(s){return !!graceClaim(s);}
