function notifBuild(){var out=[],nowK=dn(TODAY)*1440+12*60;
 attention().forEach(function(a){out.push({id:'a|'+a.h+'|'+a.sub,kind:nKind(a),act:true,t:a.t,sub:a.sub,h:a.h,c:a.c,k:nowK});});
 S.sales.forEach(function(x){if(x.status==='draft')return;(x.events||[]).forEach(function(e){if(!/^-?\d+\|\d\d:\d\d$/.test(e.t||''))return;var k=evKey(e);if(nowK-k>21*1440)return;var lab=evLab(e.x),kind=lab==='Pago observado'||lab==='Venta saldada'?'pago':/Cotización (aceptada|rechazada)/.test(lab)?'cotizacion':lab==='Enlace abierto'?'enlace':/^(Venta anulada|Vencimiento reprogramado)/.test(e.x)?'venta':/^Solicitud/.test(e.x)?'solicitud':null;if(!kind)return;out.push({id:'e|'+x.id+'|'+e.t+'|'+e.x.slice(0,24),kind:kind,act:false,t:((kind==='venta'||kind==='solicitud')?e.x.split(':')[0].split('.')[0]:lab)+' · '+x.id,sub:buyer(x.buyerId).name+' · '+e.x.slice(0,90),h:'#/sales/'+x.id,t2:e.t,k:k});});});
 S.buyers.forEach(function(b){var d=b.kybDoc||{};Object.keys(d).forEach(function(key){var ok=(key==='reg'||key==='bank')?(b.kyb&&b.kyb[key]):(b.comp&&b.comp[key]);if(ok||!d[key])return;var dd=d[key].date||TODAY;out.push({id:'d|'+b.id+'|'+key,kind:'verif',act:false,t:'Documento en verificación',sub:b.name+' · '+({reg:'Registro mercantil',bank:'Cuenta bancaria empresarial',rif:'RIF de la empresa',addr:'Prueba de dirección fiscal'}[key]||key),h:'#/buyers/'+b.id,t2:dn(dd)+'|09:00',k:dn(dd)*1440+540});});});
 (S.portalLog||[]).forEach(function(l,ix){if(!l.ok||!l.buyerId)return;var m=/^(-?\d+)\|/.exec(l.t||'');if(!m)return;out.push({id:'p|'+l.t+'|'+l.buyerId,kind:'portal',act:false,t:'Consulta en el portal de pagos',sub:buyer(l.buyerId).name,h:'#/config/portal',t2:l.t,k:evKey({t:l.t})});});
 return out.filter(function(n){return npfOn(n.kind);}).sort(function(a,b){return (b.act?1:0)-(a.act?1:0)||b.k-a.k;});}
function nU(){var u=sessUser();u.nread=u.nread||{};u.npref=u.npref||{};u.ndigest=u.ndigest||'daily';return u;}
function nIsRead(id){return !!nU().nread[id];}
