 var prefs='<section class="panel"><h2>Tus preferencias '+info('Son solo tuyas: cada persona del equipo elige las categorías que ve y cada cuánto recibe un resumen por correo.')+'</h2><p class="muted small">'+esc(sessUser().name)+' · '+roleLabel(myRole())+'</p><div class="prows">'+NCAT.map(function(c){return '<div class="prow"><span>'+c[1]+'</span><span></span><span class="pact"><label class="tgsw"><input type="checkbox" data-act="nPref" data-k="'+c[0]+'"'+(npfOn(c[0])?' checked':'')+' aria-label="'+c[1]+'"><span class="tgk"></span></label></span></div>';}).join('')+'</div>'+fld('ndg','Resumen por correo','<select id="ndg" data-ndig><option value="daily"'+(nU().ndigest==='daily'?' selected':'')+'>Diario</option><option value="weekly"'+(nU().ndigest==='weekly'?' selected':'')+'>Semanal</option><option value="off"'+(nU().ndigest==='off'?' selected':'')+'>Nunca</option></select>')+'</section>';
