function cfgSave(){try{var B=S.brand,o={v:1,brand:B.wide?{wide:B.wide,sq:B.sq,nm:B.nm,trim:B.trim,fit:B.fit,zoom:B.zoom,px:B.px,py:B.py,small:B.small,ed:B.ed||null,orig:(B.orig&&B.orig.length<900000)?B.orig:null}:null,mk:S.mk,prefs:S.users.map(function(u){return {id:u.id,nread:u.nread||{},npref:u.npref||{},ndigest:u.ndigest||'daily'};})},j=JSON.stringify(o);if(j!==cfgSave.last){localStorage.setItem('fluye.cfg',j);cfgSave.last=j;}}catch(e){}}
