function hasOverdue(b){return S.sales.some(function(x){if(x.buyerId!==b.id||x.status!=='active'||balance(x)<=0.005)return false;var ni=nextItem(x);return !!(ni&&ni.n<0);});}
var ISLR_LBL={bienes:'Venta de bienes',servicios:'Prestación de servicios',obra:'Obra o proyecto',suministro:'Suministro e instalación',arrendamiento:'Arrendamiento',otro:'Otra operación'};
function retOn(){return !!(S.ret&&S.ret.on&&MKT().taxes.retentions);}
function retOf(b){return (retOn()&&b&&!isPn(b)&&b.ret&&(b.ret.iva||b.ret.islr))?b.ret:null;}
function retApplies(s){return !!retOf(buyer(s.buyerId));}
function islrConcept(op,nat){var c=catOf(op);if(c&&c[3])return c[3];var n=nat||'producto';return n==='servicio'?'servicios':n==='alquiler'?'arrmuebles':'bienes';}
function islrPct(op,nat){var v=S.ret.islr[islrConcept(op,nat)];return v===undefined?0:v;}
function islrPctSale(s){return islrPct(catsOf(s)[0],s.opNat);}
function pctTxt(v){return String(Math.round(v*100)/100).replace('.',sepD())+' %';}
function catSplitNeeded(o){var cs=(o.ops&&o.ops.length)?o.ops:[o.op];if(cs.length<2)return false;var pc=cs.map(function(k){return islrPct(k,o.opNat);});return !pc.every(function(v){return v===pc[0];});}
function fisOf(s){if(s.fis)return s.fis;var r=S.ret.rate,base=r2(s.amount/(1+r/100));return {rate:r,exempt:0,base:base,iva:r2(s.amount-base),control:'',est:true};}
function fisCalc(amount,rate,exempt){var ex=Math.max(0,Math.min(amount,exempt||0)),base=r2((amount-ex)/(1+rate/100));return {rate:rate,exempt:r2(ex),base:base,iva:r2(amount-ex-base)};}
function invsOf(s){return s.invs||[];}
function invTotal(s){return r2(invsOf(s).reduce(function(a,v){return a+v.amount;},0));}
function retFull(s){var r=retOf(buyer(s.buyerId))||{},t={iva:0,islr:0};invsOf(s).forEach(function(v){if(r.iva&&S.ret.pct>0)t.iva+=v.iva*S.ret.pct/100;if(r.islr)t.islr+=v.base*islrPctSale(s)/100;});var iva=r2(t.iva),islr=r2(t.islr);return {iva:iva,islr:islr,t:r2(iva+islr)};}
function retEst(s){var r=retOf(buyer(s.buyerId))||{},f=fisOf(s),iva=(r.iva&&S.ret.pct>0)?r2(f.iva*S.ret.pct/100):0,islr=r.islr?r2(f.base*islrPctSale(s)/100):0;return {iva:iva,islr:islr,t:r2(iva+islr)};}
function retEntries(s){return s.payments.filter(function(q){return q.method==='ret';});}
function retAll(s){return retEntries(s).concat(s.retNo||[]);}
function retForPay(s,gross){if(!retApplies(s))return {iva:0,islr:0,t:0};var F=retFull(s),got=retAll(s),gi=got.filter(function(q){return q.tax==='iva';}).reduce(function(a,q){return a+q.amount;},0),gs=got.filter(function(q){return q.tax==='islr';}).reduce(function(a,q){return a+q.amount;},0),iva=Math.max(0,r2(F.iva-gi)),islr=Math.max(0,r2(F.islr-gs));if(iva+islr>gross){var k=gross/(iva+islr);iva=r2(iva*k);islr=r2(islr*k);}return {iva:iva,islr:islr,t:r2(iva+islr)};}
function legalDue(d){var dt=new Date(d.getFullYear(),d.getMonth(),d.getDate()),c=(S.ret.period==='q'&&dt.getDate()<=15)?new Date(dt.getFullYear(),dt.getMonth(),16):new Date(dt.getFullYear(),dt.getMonth()+1,1),n=0;for(var g=0;g<20;g++){var w=c.getDay();if(MKT().weekend.indexOf(w)<0){n++;if(n===2)return c;}c=addDays(c,1);}return c;}
function retSt(q){if(q.noAt)return 'norec';if(q.st==='ok')return 'ok';if(q.st==='review')return 'review';return dn(TODAY)>dn(q.date)+S.ret.alertDays?'late':'pending';}
