function retRemind(q){var d0=dn(q.date),ds=S.ret.remind.map(function(x){return d0+x;}),last=ds[ds.length-1],t=dn(TODAY);for(var k=1;k<60;k++){var nx=last+k*S.ret.every;ds.push(nx);if(nx>t)break;}var sent=ds.filter(function(x){return x<=t;}).length,nxt=ds.filter(function(x){return x>t;})[0];return {sent:sent,next:nxt?dnDate(nxt):null};}
function retBs(s,v){return s.cur==='VES'?null:r2(v*crossRate(s.cur,'VES',dn(s.issue)));}
function retStats(b){var es=[];S.sales.forEach(function(x){if(x.buyerId===b.id)retAll(x).forEach(function(q){es.push(q);});});var ok=es.filter(function(q){return q.st==='ok';}),onT=ok.filter(function(q){return q.okAt&&dn(q.okAt)<=dn(q.date)+S.ret.alertDays;}).length,open=es.filter(function(q){var t=retSt(q);return t==='pending'||t==='late'||t==='review';}).length;return {n:es.length,ok:ok.length,onT:onT,open:open};}
