function retCaps(s,due){var r=retOf(buyer(s.buyerId))||{},got=retAll(s),gi=got.filter(function(q){return q.tax==='iva';}).reduce(function(a,q){return a+q.amount;},0),gs=got.filter(function(q){return q.tax==='islr';}).reduce(function(a,q){return a+q.amount;},0),iv=invsOf(s).reduce(function(a,v){return a+v.iva;},0),bs=invsOf(s).reduce(function(a,v){return a+v.base;},0);return {iva:r.iva?Math.max(0,r2(iv-gi)):0,islr:r.islr?Math.max(0,r2(bs*0.05-gs)):0,due:due};}
