function cobSpark(c){
 var pts=[];for(var i=13;i>=0;i--){var day=addDays(TODAY,-i),sum=0;S.sales.forEach(function(x){if(x.cur===c)x.payments.forEach(function(q){if(q.date.getMonth()===TODAY.getMonth()&&q.date<=day)sum+=q.amount;});});pts.push(sum);}
 var mx=Math.max.apply(null,pts)||1;
 var dd=pts.map(function(v,i){return (i?'L':'M')+(i*64/13).toFixed(1)+' '+(20-(v/mx)*16).toFixed(1);}).join('');
 return '<svg class="sp" viewBox="0 0 64 22" aria-hidden="true"><path d="'+dd+'" fill="none" style="stroke:var(--chart-1)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}
