function monthsSince(txt){var m=/^(\d{4})-(\d{2})$/.exec(txt||'');if(!m)return null;return (TODAY.getFullYear()-parseInt(m[1],10))*12+(TODAY.getMonth()-(parseInt(m[2],10)-1));}
var nowTm=function(){return dn(TODAY)*1000+(++S.tmc);};
function scName(){return S.dec.scname==='op'?'Score operativo':S.dec.scname==='pay'?'Comportamiento de pago':'Índice de fiabilidad operativa';}
function lvTone(l){return (l==='Muy alto'||l==='Alto')?'ok':l==='Moderado'?'info':l==='Bajo'?'warn':'err';}
function engine(b,asTm){
 var A=asTm!==undefined?asTm:dn(TODAY)*1000+999,aD=Math.floor(A/1000),G=SCM.grace;
 var ts=S.sales.filter(function(x){return x.buyerId===b.id&&x.actTm!==undefined&&x.actTm<A&&x.status!=='draft'&&x.status!=='cancelled';});
 var n=0,y=0,m=0,mon=0,D=0;
 ts.forEach(function(x){
  var due=dn((S.policy.reschedScore==='new')?x.due:(x.dueOrig||x.due)),closed=x.status==='paid'&&x.paidTm!==undefined&&x.paidTm<=A,pd=closed?dn(x.paidAt):null;
  if(closed){n++;if(pd<=due+G)y++;}
  if(due+G<aD){m++;if(closed&&pd<=due+G)mon++;D+=Math.min(30,closed?Math.max(pd-due,0):aD-due);}
 });
 var k=b.kyb||{reg:false,age:0,bank:false},posture=S.dec.method==='manual'?'manual':'assisted',dc=b.kybDoc||{},dok=function(key){var d=dc[key];return !!(d&&d.date&&dn(d.date)<=aD);},rL=k.reg?1:(dok('reg')?SCM.prov:0),bL=k.bank?1:(dok('bank')?SCM.prov:0),ageY=k.age>0?k.age:(dok('reg')&&dc.reg.year?Math.max(0,TODAY.getFullYear()-dc.reg.year):0),ageF=k.age>0?1:(ageY>0?SCM.prov:0),prov=(!k.reg&&dok('reg'))||(!k.bank&&dok('bank'));
 if(n===0){return {mode:'bootstrap',boot:(!k.reg&&!dok('reg'))?'B3':((k.bank||dok('bank'))&&posture!=='manual')?'B1':'B2',k:k,n:0,prov:prov};}
 var c=n/(n+SCM.k),b1=m?mon/m:SCM.pon,b2=y/n,b3=m?D/(30*m):SCM.pl,s2=Math.max(0,Math.min(1,ageY/5))*ageF;
 var ct=[
  {v:SCM.s1*rL,t:k.reg?'Registro mercantil verificado':rL?'Registro mercantil cargado, provisional':'Registro mercantil sin verificar'},
  {v:SCM.s2*s2,t:'Antigüedad de la empresa: '+ageY+(ageY===1?' año':' años')+((k.age>0||!ageY)?'':', provisional')},
  {v:SCM.s3*bL,t:k.bank?'Cuenta bancaria empresarial verificada':bL?'Cuenta bancaria empresarial cargada, provisional':'Cuenta bancaria empresarial sin verificar'},
  {v:c*SCM.bon*(b1-SCM.pon),t:m?'Cuotas pagadas a tiempo: '+mon+' de '+m+(b1>=SCM.pon?' (mejor que lo normal)':' (por debajo de lo normal)'):'Sin cuotas vencidas todavía'},
  {v:c*SCM.bs*(b2-SCM.ps),t:'Operaciones cerradas sin atraso: '+y+' de '+n+(b2>=SCM.ps?' (mejor que lo normal)':' (por debajo de lo normal)')},
  {v:c*SCM.bl*(b3-SCM.pl),t:m?'Atraso promedio de '+(D/m).toFixed(1).replace('.',sepD())+' días por cuota':'Sin atrasos registrados'}
 ];
 var z=SCM.b0;ct.forEach(function(q){z+=q.v;});
 var os=Math.round(100/(1+Math.exp(-z))),lvl=os>=80?'Muy alto':os>=65?'Alto':os>=50?'Moderado':os>=35?'Bajo':'Crítico',cl=c<.33?'Baja':c<.6?'Media':'Alta';
 return {mode:'observed',os:os,lvl:lvl,c:c,cl:cl,n:n,y:y,m:m,mon:mon,D:D,k:k,z:z,prov:prov,drivers:ct.slice().sort(function(p,q){return Math.abs(q.v)-Math.abs(p.v);}).slice(0,3)};
}
function snapScore(s){if(!s.snapshot.sc)s.snapshot.sc=engine(buyer(s.buyerId),s.actTm);return s.snapshot.sc;}
var BOOT={B1:'Registro mercantil y cuenta bancaria verificados, con pago asistido.',B2:'Registro mercantil verificado; falta la cuenta bancaria verificada o el pago es manual.',B3:'Registro mercantil sin verificar.'};
function drvList(r){return '<ul class="rsn">'+r.drivers.map(function(q){return '<li class="'+(q.v>=0?'ok':'no')+'">'+ic(q.v>=0?'check':'alert')+'<span>'+q.t+'</span></li>';}).join('')+'</ul>';}
