function rank(q,lab){var n=norm(lab);return n.indexOf(q)===0?0:(' '+n).indexOf(' '+q)>=0?1:2;}
function cbMatches(q){var qq=norm(q||''),all=S.buyers.filter(function(x){return clState(x)!=='archived'&&(!qq||norm(x.name+' '+x.rif+' '+(x.extId||'')).indexOf(qq)>=0);});if(qq)all.sort(function(a,b){return rank(qq,a.name)-rank(qq,b.name);});return all;}
