function salePhases(s){
 var b=buyer(s.buyerId),st=s.status,pr=s.proposal,ps=pr?propState(s):null,draft=st==='draft',paid=st==='paid',its=draft?itemsOf(s):alloc(s),multi=multiPlan(s),G=SCM.grace,A=[];
 var add=function(t,state,cap,cap2){A.push({t:t,st:state,cap:cap,cap2:cap2||''});};
 if(pr){
  add('Cotización','done','Enviada el '+dfmt(pr.sentAt));
  if(!draft||ps==='accepted')add('Aprobación','done','Aprobada el '+dfmt(pr.acceptedAt||pr.sentAt));
  else if(ps==='declined')add('Aprobación','err','Rechazada por el cliente');
  else if(ps==='expired')add('Aprobación','err','Venció el '+dfmt(pr.validUntil));
  else add('Aprobación','cur','En espera de aprobación · válida hasta '+dfmt(pr.validUntil));
  add('Activación',draft?(ps==='accepted'?'cur':'todo'):'done',draft?(ps==='accepted'?'Lista para activar':(ps==='sent'?'Cuando el cliente apruebe':'No se activa')):'Activa desde '+dfmt(s.issue));
 } else add('Venta',draft?'cur':'done',draft?'Lista para revisar':'Activa desde '+dfmt(s.issue));
 var vals=its.filter(function(q){return q.type==='valuacion';}),rec=its.filter(function(q){return q.type==='recepcion';});
 if(vals.length){var ap=vals.filter(function(q){return q.apv;}).length,em=vals.filter(function(q){return q.state==='emitida';})[0];
  add('Valuaciones',draft?'todo':(ap===vals.length?'done':'cur'),draft?'Tras activar':(em?'Valuación '+(vals.indexOf(em)+1)+' en espera de aprobación':ap+' de '+vals.length+' valuaciones aprobadas'),(!draft&&em)?ap+' de '+vals.length+' valuaciones aprobadas':'');}
 else if(rec.length){add('Recepción',draft?'todo':(rec[0].apAt?'done':'cur'),draft?'Tras activar':(rec[0].apAt?'Recepción confirmada el '+dfmt(rec[0].apAt):'Recepción por confirmar'));}
 var n=its.length,nPaid=draft?0:its.filter(function(q){return q.bal<=0.005;}).length,cuotas=its.every(function(q){return q.type==='cuota';});
 if(draft)add('Pagos','todo','Tras activar',multi?planLabel(s):'');
 else if(paid)add('Pagos','done',n>1?nPaid+' de '+n+(cuotas?' cuotas pagadas':' pagos realizados'):'Pago completado el '+dfmt(s.paidAt));
 else{var ni=nextItem(s),od=ni&&ni.n<0,c2;
  if(s.undated||!ni)c2='Sin fecha aún';
  else c2=(n>1?(od?'Atrasada: ':'Próxima: ')+'<span>'+esc(ni.c.label)+'</span> · ':'')+'<span>'+dueTxt(ni.c.due)+'</span>';
  add('Pagos',od?'warn':'cur',n>1?nPaid+' de '+n+(cuotas?' cuotas pagadas':' pagos realizados'):'Pago único · saldo '+mt(balance(s),s.cur),c2);}
 if(paid){var late=dn(s.paidAt)-dn(s.due),dd=function(v){return v+(v===1?' día':' días');},cap=late<0?'Pagado '+dd(-late)+' antes':late===0?'Pagado a tiempo':late<=G?'Pagado con '+dd(late)+' de atraso · dentro de la gracia':'Pagado con '+dd(late)+' de atraso';
  add('Completado',late>G?'doneLate':'done',cap,hasCredit(b)?'Score actualizado':'Historial actualizado');}
 else add('Completado','todo','Al saldar todo');
 return '<section class="phases" style="--n:'+A.length+'" aria-label="Fases de la venta">'+A.map(function(q,i){var cl=q.st==='doneLate'?'done late':q.st==='warn'?'cur warn':q.st,dot=(q.st==='done'||q.st==='doneLate')?ic('check'):q.st==='err'?ic('alert'):(i+1);return '<div class="ph '+cl+'"'+((q.st==='cur'||q.st==='warn')?' aria-current="step"':'')+'><span class="dot">'+dot+'</span><div class="tt">'+q.t+'</div><div class="cp">'+q.cap+'</div>'+(q.cap2?'<div class="cp cp2">'+q.cap2+'</div>':'')+'</div>';}).join('')+'</section>';
}
