 if(key){var mn=document.querySelector('.main');if(mn)mn.insertAdjacentHTML('beforeend',refHtml(key));}
 if(S.coNotice&&a!=='entry'){var mn2=document.querySelector('.main');if(mn2)mn2.insertAdjacentHTML('afterbegin','<div class="banner warn" id="co-notice" role="status" style="margin-bottom:16px;align-items:center"><div>'+esc(S.coNotice)+'</div><button class="btn btn-t btn-sm" data-act="coNoticeX">Cerrar</button></div>');}
 if(a!=='entry'&&a!=='recover'&&a!=='join'&&a!=='pay'&&a!=='msg'&&a!=='portal'&&S.dec.role==='nc'){location.replace('#/entry');return;}
