function countUp(){
 if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 Array.prototype.forEach.call(document.querySelectorAll('[data-cnt]'),function(el){
  var to=parseFloat(el.getAttribute('data-cnt')),c=el.getAttribute('data-cur'),pc=el.hasAttribute('data-pct'),t0=null;
  function f(ts){if(!t0)t0=ts;var k=Math.min(1,(ts-t0)/700),v=to*(1-Math.pow(1-k,3));if(pc)el.textContent=Math.round(v)+'%';else el.innerHTML=parts(r2(v),c);if(k<1)requestAnimationFrame(f);}
  requestAnimationFrame(f);
 });
}
